created=['content/isc2-cc-2026/learning/published/lessons/lesson-d1-11-control-functions.json','css/learning-control-functions.css','js/ui/learning/control-functions-presentations.js','tools/verify-learning-control-functions.mjs','docs/plans/isc2-cc-2026/lesson-d1-11-implementation.md']
assert set(changed)==set(expected),(changed,expected);assert not missing
catalogPath='content/isc2-cc-2026/learning/published/catalog.json';catalog=read(root/catalogPath);before=read(qa/'catalog-before.json');copy=json.loads(json.dumps(catalog));copy['revision']=before['revision'];copy['domains'][0]['objectives'][3]['lessons']=[x for x in copy['domains'][0]['objectives'][3]['lessons'] if x['id']!='lesson-d1-11-control-functions'];assert copy==before
lessonSummaries=[l for d in catalog['domains'] for o in d['objectives'] for l in o['lessons'] if l['status']=='published'];assert len(lessonSummaries)==11;assert sum(len(read(root/'content/isc2-cc-2026/learning/published'/l['lessonPath'])['slides']) for l in lessonSummaries)==91
stage=root/'.learning-preview/run-b3342e54-93b0-41e5-a4cd-e2453d24309b';stageFiles=['index.html',catalogPath,created[0],created[1],created[2],'js/ui/learning/renderers.js','js/ui/learning/lesson-info.js'];assert all(hashfile(root/p)==hashfile(stage/p) for p in stageFiles)
metrics=read(qa/'browser-measurements.json');required=[f'{size}-{lang}-slide-0{i}' for size in [1366,1920] for lang in ['th','en'] for i in range(1,10)];states=[f'{size}-{lang}-context-{i}' for size in [1366,1920] for lang in ['th','en'] for i in range(3)];names=[x['name'] for x in metrics];assert len(names)==48 and set(names)==set(required+states);assert all((qa/(n+'.jpg')).exists() for n in names);assert all(not x['outside'] and x['scroll']==x['client'] and x['mode']=='presentation' for x in metrics)
failNames=lambda p:[re.sub(r' \([0-9.]+ms\)$','',s[2:]) for s in Path(p).read_text(encoding='utf-8-sig').splitlines() if s.startswith('✖ ')][:5]
failures=failNames(qa/'vocabulary-verification.txt');assert len(failures)==5 and failures==failNames(root/'artifacts/qa/lesson-d1-10-control-categories/vocabulary-verification.txt')
priorLessons=[p for p in old if p.startswith('content/isc2-cc-2026/learning/published/lessons/') and p.endswith('.json')];assert len(priorLessons)==10 and all(hashfile(root/p)==old[p] for p in priorLessons)
protected=[p for p in old if p.startswith(('data/','ISC2 Update 2026/Domain 1/')) or p in ['js/core/learning-progress.js','js/ui/learning/viewer.js','js/ui/screen-quiz.js','js/ui/screen-vocabulary.js']];assert all(hashfile(root/p)==old[p] for p in protected)
result={'baselineFiles':len(base),'unchanged':len(base)-len(changed),'changed':sorted(changed),'missing':missing,'createdImplementationAndDocs':created,'requiredScreenshots':36,'feedbackScreenshots':12,'allRequiredPresent':True,'noOverflow':True,'presentationOnly':True,'minimumFooterGap':min(x['footerGap'] for x in metrics),'tenPriorLessonsUnchanged':True,'priorCatalogPreserved':True,'stagingParity':True,'stagingFiles':stageFiles,'protectedSourceQuizVocabularyBanksUnchanged':True,'protectedBankCount':read(qa/'protected-bank-count.json'),'historicalVocabularyFailureNamesUnchanged':True,'historicalFailures':failures,'finalDocumentationUpdated':True}
(qa/'integrity-check.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
manifest={'modifiedFromTaskEntryBaseline':sorted(changed),'createdImplementationAndDocs':created,'createdEvidenceFiles':sorted('artifacts/qa/lesson-d1-11-control-functions/'+p.name for p in qa.iterdir() if p.is_file() and p.name!='delivery-manifest.json')+['artifacts/qa/lesson-d1-11-control-functions/delivery-manifest.json']};(qa/'delivery-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
